          "air_density_kg_m3": 1.225,
          "known_flag_height_m": 1.25,
          "effective_sheet_stiffness_n_m": 180.0,
          "response_time_seconds": 0.65
        },
        "expected_level": "medium deformation consistent with 5.0 m/s airflow",
